<?php
require_once __DIR__.'/../api/bootstrap.php';require_login();$m=current_medico();$id=(int)($_GET['id']??0);
$s=db()->prepare('SELECT a.*,p.nome paciente_nome,p.cpf paciente_cpf FROM atestados a JOIN pacientes p ON p.id=a.paciente_id WHERE a.id=? AND a.medico_id=?');$s->execute([$id,$m['id']]);$a=$s->fetch();if(!$a)exit('Atestado não encontrado.');
$body=trim((string)$a['conteudo_personalizado']);
$vars=['{{PACIENTE}}'=>$a['paciente_nome'],'{{CPF}}'=>$a['paciente_cpf'],'{{CID}}'=>$a['cid_codigo'],'{{CID_DESCRICAO}}'=>$a['cid_descricao'],'{{MEDICO}}'=>$m['nome_completo'],'{{CRM}}'=>$m['crm'].'/'.$m['uf'],'{{ESPECIALIDADE}}'=>$m['especialidade'],'{{DATA}}'=>date('d/m/Y',strtotime($a['data_emissao'])),'{{INICIO}}'=>date('d/m/Y',strtotime($a['inicio_afastamento'])),'{{FIM}}'=>date('d/m/Y',strtotime($a['fim_afastamento'])),'{{DIAS}}'=>$a['dias_afastamento']];
$body=$body!==''?strtr($body,$vars):'Atesto, para os devidos fins, que <strong>'.e($a['paciente_nome']).'</strong> foi submetido(a) a avaliação médica e necessita de afastamento das atividades no período de <strong>'.e(date('d/m/Y',strtotime($a['inicio_afastamento']))).' a '.e(date('d/m/Y',strtotime($a['fim_afastamento']))).'</strong>, totalizando <strong>'.e($a['dias_afastamento']).' dia(s)</strong>.';
if($a['conteudo_personalizado']!=='')$body=nl2br(e($body));$base=medical_base();$valid=(($_SERVER['HTTPS']??'')!=='off'&&($_SERVER['HTTPS']??'')!=='')?'https':'http';$validation=$valid.'://'.$_SERVER['HTTP_HOST'].$base.'/validar.php?id='.rawurlencode($a['codigo_validacao']);
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=e($a['titulo'])?></title><style>body{font:15px Arial;max-width:850px;margin:20px auto;line-height:1.65;background:#f5f7fa}.doc{background:#fff;border:1px solid #ddd;padding:45px;min-height:900px}.head{text-align:center;border-bottom:2px solid #163b63;padding-bottom:18px}.sign{text-align:center;margin-top:80px}.meta{font-size:12px;color:#666}@media print{body{background:#fff;margin:0}.no-print{display:none}.doc{border:0}}</style></head><body><div class="no-print"><button onclick="window.print()">Imprimir / Salvar PDF</button></div><article class="doc"><header class="head"><?php if(!empty($m['logo_path'])&&file_exists(__DIR__.'/../'.$m['logo_path'])):?><img src="<?=e($base.'/assinatura.php?medico='.$m['id'].'&tipo=logo')?>" style="max-width:220px;max-height:90px"><br><?php endif;?><strong><?=e($m['nome_completo'])?></strong><br>CRM <?=e($m['crm'].'/'.$m['uf'])?><?php if($m['especialidade']):?> · <?=e($m['especialidade'])?><?php endif;?></header><h1 style="text-align:center"><?=e($a['titulo']?:'ATESTADO MÉDICO')?></h1><p><?=$body?></p><?php if($a['cid_codigo']):?><p><b>CID-10:</b> <?=e($a['cid_codigo'])?> — <?=e($a['cid_descricao'])?></p><?php endif;?><?php if($a['incapacidade_restricao']):?><p><b>Limitação/restrição:</b><br><?=nl2br(e($a['incapacidade_restricao']))?></p><?php endif;?><?php if($a['info_clinica']):?><p><?=nl2br(e($a['info_clinica']))?></p><?php endif;?><p><?=e(date('d/m/Y',strtotime($a['data_emissao'])))?></p><div class="sign"><?php if(!empty($m['assinatura_path'])):?><img src="<?=e($base.'/assinatura.php?medico='.$m['id'])?>" style="max-width:220px;max-height:90px"><br><?php endif;?><b><?=e($m['nome_completo'])?></b><br>CRM <?=e($m['crm'].'/'.$m['uf'])?></div><div style="text-align:center;margin-top:25px"><img src="<?=e($base.'/qr.php?id='.rawurlencode($a['codigo_validacao']))?>" style="width:150px;height:150px"><br><small>Validação de autenticidade</small></div><hr><div class="meta">Código: <?=e($a['codigo_validacao'])?><br><?=e($validation)?></div></article></body></html>